    private static async Task<(CommandResult Result, RecordedRequest Request)> RunWithApiResponseAsync(
        string[] args,
        string responseBody,
        int statusCode = 200,
        string reasonPhrase = "OK")
    {
        using var handler = new RecordingHandler(responseBody, statusCode, reasonPhrase);
        using var env = new EnvironmentScope("http://127.0.0.1", "jt_test_key");
        var result = await RunAsync(args, (baseUrl, key) =>
        {
            var http = new HttpClient(handler, disposeHandler: false) { BaseAddress = new Uri(baseUrl) };
            http.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", key);
            return http;
        });

        return (result, handler.Request ?? throw new InvalidOperationException("No HTTP request was recorded."));
    }

    private static async Task<CommandResult> RunAsync(
        string[] args,
        Func<string, string, HttpClient>? httpClientFactory = null)
    {
        using var output = new StringWriter(CultureInfo.InvariantCulture);
        using var error = new StringWriter(CultureInfo.InvariantCulture);
        var console = AnsiConsole.Create(new AnsiConsoleSettings
        {
            Out = new AnsiConsoleOutput(output),
            Interactive = InteractionSupport.No,
        });

        var exitCode = await JobTrackCli.CreateCommandApp(console, error, httpClientFactory).RunAsync(args);
        return new CommandResult(exitCode, output.ToString(), error.ToString());
    }

    private static Task<CommandResult> RunAsync(params string[] args) => RunAsync(args, httpClientFactory: null);

    private sealed record CommandResult(int ExitCode, string Output, string Error);

    private sealed record RecordedRequest(
        string Method,
        string Path,
        string Query,
        string? Authorization,
        string Body);

    private sealed class RecordingHandler(string responseBody, int statusCode, string reasonPhrase) : HttpMessageHandler
    {
        public RecordedRequest? Request { get; private set; }

        protected override async Task<HttpResponseMessage> SendAsync(
            HttpRequestMessage request,
            CancellationToken cancellationToken)
        {
            var body = request.Content is null
                ? string.Empty
                : await request.Content.ReadAsStringAsync(cancellationToken);
            Request = new RecordedRequest(
                request.Method.Method,
                request.RequestUri?.AbsolutePath ?? string.Empty,
                request.RequestUri?.Query ?? string.Empty,
                request.Headers.Authorization?.ToString(),
                body);

            return new HttpResponseMessage((HttpStatusCode)statusCode)
            {
                ReasonPhrase = reasonPhrase,
                Content = new StringContent(responseBody, Encoding.UTF8, "application/json"),
            };
        }
    }

    private sealed class EnvironmentScope : IDisposable
    {
        private readonly string? _apiUrl = Environment.GetEnvironmentVariable(JobTrackCli.ApiUrlEnv);
        private readonly string? _apiKey = Environment.GetEnvironmentVariable(JobTrackCli.ApiKeyEnv);

        public EnvironmentScope(string? apiUrl, string? apiKey)
        {
            Environment.SetEnvironmentVariable(JobTrackCli.ApiUrlEnv, apiUrl);
            Environment.SetEnvironmentVariable(JobTrackCli.ApiKeyEnv, apiKey);
        }

        public void Dispose()
        {
            Environment.SetEnvironmentVariable(JobTrackCli.ApiUrlEnv, _apiUrl);
            Environment.SetEnvironmentVariable(JobTrackCli.ApiKeyEnv, _apiKey);
        }
    }
