        context.Data as CommandRuntime
        ?? throw new InvalidOperationException("Command runtime is not configured.");

    protected async Task<int> SendAndRenderAsync(
        CommandRuntime runtime,
        HttpMethod method,
        string path,
        object? payload,
        string commandName,
        Action<string> renderSuccess,
        CancellationToken cancellationToken)
    {
        var response = await runtime.SendAsync(method, path, payload, cancellationToken);
        if (!response.IsSuccessStatusCode)
        {
            runtime.Error.WriteLine($"{commandName}: {response.StatusCode} {response.ReasonPhrase}");
            RenderErrorBody(runtime.Error, response.Body);

            return 1;
        }

        renderSuccess(response.Body);
        return 0;
    }

    private static void RenderErrorBody(TextWriter writer, string body)
    {
        if (string.IsNullOrWhiteSpace(body))
        {
            return;
        }

        UntrustedJobTrackOutput.WriteBlock(
            writer,
            output => output.WriteLine($"Raw error body: {UntrustedJobTrackOutput.Value(body)}"));
    }
}

internal static class TaskOutputPresenter
{
    public static void RenderList(TextWriter writer, string body, bool json)
    {
        if (json)
        {
            RenderJson(writer, body);
            return;
        }

        if (string.IsNullOrWhiteSpace(body))
        {
            return;
        }

        var rows = TaskJson.ReadTaskRows(body);
        if (rows is null)
        {
            RenderRawBody(writer, body);
            return;
