                output.WriteLine(
                    $"{UntrustedJobTrackOutput.Value(row.ShortCode)}\t" +
                    $"{UntrustedJobTrackOutput.Value(row.Title)}\t" +
                    $"{UntrustedJobTrackOutput.Value(row.Status)}");
            }
        });
    }

    public static void RenderDetails(TextWriter writer, string body, bool json, string emptyBodyMessage)
    {
        if (json)
        {
            RenderJson(writer, body);
            return;
        }

        if (string.IsNullOrWhiteSpace(body))
        {
            if (!string.IsNullOrWhiteSpace(emptyBodyMessage))
            {
